#!/usr/bin/env python3
"""Checks for a page generated by the explain-diff skill.

Static checks parse the saved HTML. Dynamic checks (--browser) load it in
Chromium through Playwright, block all network access, click every code
reference, and watch for script execution, errors, and layout overflow.

Usage:
  python3 validate_page.py PAGE.html [--browser] [--canary STRING ...]

Set CHROMIUM_PATH to use a Chromium binary other than the one Playwright downloaded.

Exit code 0 when no check fails. Warnings do not fail the run.
"""
import argparse
import json
import os
import re
import sys
from html.parser import HTMLParser

NET_APIS = re.compile(r"(\bfetch\s*\(|XMLHttpRequest|\bWebSocket\b|\bEventSource\b|sendBeacon|importScripts|new\s+Image\s*\()")
# innerHTML = "" only clears a container, so it is allowed; any other innerHTML write is a sink.
SINKS = re.compile(r"(\.innerHTML\s*(?:\+)?=(?!=)(?!\s*(?:''|\"\"|``)\s*[;,)}\n])|\.outerHTML\s*(?:\+)?=(?!=)|insertAdjacentHTML|document\.write\s*\(|\beval\s*\(|new\s+Function\s*\()")
URL_ATTRS = {"src", "href", "action", "poster", "data", "formaction", "srcset", "xlink:href"}
SECTIONS = ["Background", "Intent", "Review", "Governance", "Intuition", "Code", "Quiz", "Gate"]
MARKS = {"met", "notmet", "na"}
GOV_FORMATS = {"md", "pdf", "docx"}
# Words that would mean the page, not the reviewer, decided a control.
GOV_VERDICT = re.compile(r"\bgovernance (?:passed|is (?:met|clear(?:ed)?|satisfied))\b|\ball (?:governance )?controls (?:are )?(?:met|pass(?:ed)?)\b", re.I)
RISKS = {"high", "medium", "low"}
UNDO_KINDS = {"flag", "revert", "careful", "irreversible"}
VERDICTS = {"cause", "symptom", "unclear"}
# Words a review guide must not use: it guides the human review and never gives a verdict.
VERDICT_WORDS = re.compile(r"\bLGTM\b|\bI approve\b|\bapproved? (?:this|the) (?:PR|pull request|change|merge)\b|\bsafe to merge\b|\bready to merge\b"
                           r"|\bship it\b(?! (?:behind|with|as|in|to|on|after|once)\b)|\bno issues found\b|\blooks good to me\b"
                           r"|\b(?:P0|P1|P2|critical|major|minor) (?:bug|finding|issue)s?\b", re.I)
# A sentence that reports or quotes what someone else asked for is not the page's own verdict:
# the skill requires the page to say that planted instructions (approve, "LGTM, safe to merge") were ignored.
REPORTING = re.compile(r"\b(?:ask(?:s|ed|ing)?|says?|said|tells?|telling|told|instruct\w*|aimed at|addressed to|request(?:s|ed|ing)?"
                       r"|wants?|follow(?:ed|ing)?|ignored|treated as data|quot\w*|claims?|planted|marker|comment)\b", re.I)
QUOTED = re.compile(r'"[^"\n]{0,200}"|\u201c[^\u201d\n]{0,200}\u201d|`[^`\n]{0,200}`')


def verdict_words(text):
    """Verdict words the text says in its own voice: quoted strings and reporting sentences are left out."""
    found = set()
    for sentence in re.split(r"(?<=[.!?])\s+|\n+", QUOTED.sub(" ", text)):
        if not REPORTING.search(sentence):
            found.update(m.group(0) for m in VERDICT_WORDS.finditer(sentence))
    return sorted(found)


class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.scripts, self.styles, self.attrs, self.h2, self.tags = [], [], [], [], []
        self._cur, self._in_h2, self._h2, self._in_btn = None, False, "", 0

    def handle_starttag(self, tag, attrs):
        for k, v in attrs:
            self.attrs.append((tag, k, v or ""))
        self.tags.append(dict((k, v or "") for k, v in attrs))
        if tag == "script":
            self._cur = {"attrs": dict(attrs), "text": "", "kind": "script"}
        elif tag == "style":
            self._cur = {"text": "", "kind": "style"}
        elif tag in ("h2", "summary"):
            self._in_h2, self._h2 = True, ""
        elif tag == "button":
            self._in_btn += 1  # a toggle inside a heading is not part of its name

    def handle_endtag(self, tag):
        if tag == "script" and self._cur and self._cur["kind"] == "script":
            self.scripts.append(self._cur)
            self._cur = None
        elif tag == "style" and self._cur and self._cur["kind"] == "style":
            self.styles.append(self._cur["text"])
            self._cur = None
        elif tag in ("h2", "summary"):
            self._in_h2 = False
            self.h2.append(self._h2.strip())
        elif tag == "button" and self._in_btn:
            self._in_btn -= 1

    def handle_data(self, data):
        if self._cur is not None:
            self._cur["text"] += data
        if self._in_h2 and not self._in_btn:
            self._h2 += data


def launch(pw):
    exe = os.environ.get("CHROMIUM_PATH")
    return pw.chromium.launch(executable_path=exe) if exe else pw.chromium.launch()


def walk_refs(obj, out):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == "ref" and isinstance(v, str):
                out.add(v)
            elif k == "refs" and isinstance(v, list):
                out.update(x for x in v if isinstance(x, str))
            else:
                walk_refs(v, out)
    elif isinstance(obj, list):
        for v in obj:
            walk_refs(v, out)


def static_checks(path, canaries):
    res = []

    def add(cid, level, msg):
        res.append((cid, level, msg))

    src = open(path, encoding="utf-8").read()
    p = Page()
    p.feed(src)
    json_blocks, code_scripts = [], []
    review = governance = gate = None
    for s in p.scripts:
        t = (s["attrs"].get("type") or "").lower()
        (json_blocks if t == "application/json" else code_scripts).append(s)
        if t == "application/json" and s["attrs"].get("id") == "review-data":
            review = s
        if t == "application/json" and s["attrs"].get("id") == "governance-data":
            governance = s
        if t == "application/json" and s["attrs"].get("id") == "gate-data":
            gate = s

    # S1 external dependencies
    ext = []
    for tag, k, v in p.attrs:
        if k in URL_ATTRS and re.match(r"\s*(https?:)?//", v, re.I):
            ext.append(f"<{tag} {k}={v[:60]}>")
    css = "\n".join(p.styles)
    if re.search(r"@import|url\(\s*['\"]?\s*(https?:)?//", css, re.I):
        ext.append("CSS import or url()")
    add("S1-no-external-assets", "FAIL" if ext else "PASS", "; ".join(ext) or "none found")

    # S2 network APIs and dangerous sinks in executable script
    code = "\n".join(s["text"] for s in code_scripts)
    net = sorted(set(m.group(0) for m in NET_APIS.finditer(code)))
    add("S2-no-network-apis", "FAIL" if net else "PASS", ", ".join(net) or "none found")
    sinks = sorted(set(m.group(0) for m in SINKS.finditer(code)))
    add("S3-no-html-sinks", "FAIL" if sinks else "PASS", ", ".join(sinks) or "none found")
    inline = [f"<{t} {k}>" for t, k, v in p.attrs if k.startswith("on")]
    add("S4-no-inline-handlers", "WARN" if inline else "PASS", ", ".join(sorted(set(inline))[:5]) or "none found")

    # S5 data blocks parse and contain no raw less-than character
    parsed, bad = [], []
    for s in json_blocks:
        if "<" in s["text"]:
            bad.append("raw < in data block")
        try:
            parsed.append(json.loads(s["text"]))
        except Exception as e:
            bad.append(f"JSON parse error: {e}")
    add("S5-data-blocks-escaped", "FAIL" if bad else "PASS", "; ".join(bad) or f"{len(json_blocks)} block(s) ok")

    # S6 references resolve
    snippets = {}
    for b in parsed:
        if isinstance(b, dict) and b and all(isinstance(v, dict) and "lines" in v for v in b.values()):
            snippets.update(b)
    refs = {v for t, k, v in p.attrs if k == "data-ref"}
    for b in parsed:
        walk_refs(b, refs)
    if not snippets:
        add("S6-refs-resolve", "FAIL", "no snippet data block found")
    else:
        missing = sorted(refs - set(snippets))
        unused = sorted(set(snippets) - refs)
        add("S6-refs-resolve", "FAIL" if missing else "PASS", f"missing: {missing}" if missing else f"{len(refs)} refs resolve")
        add("S7-no-unused-snippets", "WARN" if unused else "PASS", f"unused: {unused}" if unused else "none")

    # S8 pre rules keep whitespace
    subject_pre = re.compile(r"(^|[\s>+~])pre([.#][\w-]+|\[[^\]]*\]|:[\w-]+)*$")
    pre_rules = [(sel, body) for sel, body in re.findall(r"([^{}]+)\{([^}]*)\}", css)
                 if any(subject_pre.search(s.strip()) for s in sel.split(","))]
    if pre_rules:
        ok = any(re.search(r"white-space\s*:\s*pre", body) for _, body in pre_rules)
        add("S8-pre-whitespace", "PASS" if ok else "FAIL", f"{len(pre_rules)} rule(s)")
    elif "<pre" in src or "createElement('pre')" in src or 'createElement("pre")' in src:
        add("S8-pre-whitespace", "FAIL", "pre elements without a pre CSS rule")
    else:
        add("S8-pre-whitespace", "PASS", "no pre elements")

    # S9 section order
    norm = [re.sub(r"^\d+[.)]\s*", "", h) for h in p.h2]  # accept "2. Intent" as Intent
    found = []
    for h in norm:
        if h in SECTIONS and (not found or found[-1] != h):  # a summary can wrap an h2 with the same text
            found.append(h)
    add("S9-sections", "PASS" if found == SECTIONS else "FAIL", f"found {found}")

    # S12 review guide data
    add("S12-review-data", *review_checks(review, snippets))

    # S13 the page guides the review and gives no verdict
    text = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>|<[^>]+>", " ", src)
    words = verdict_words(text)
    add("S13-no-verdict", "FAIL" if words else "PASS", ", ".join(words) or "none found")

    # S14 governance data: controls listed for the reviewer, none marked by the page
    add("S14-governance-data", *governance_checks(governance, snippets, p.attrs, text, p.tags))

    # S15 the gate exists, starts blocked, and has its data block
    add("S15-gate", *gate_checks(gate, p.attrs))

    # S10 quiz shape, when the data is statically visible
    quiz = None
    for b in parsed:
        if isinstance(b, list) and b and all(isinstance(q, dict) and "options" in q and "correct" in q for q in b):
            quiz = b
    if quiz is None:
        add("S10-quiz", "WARN", "quiz data not statically visible; check by hand")
    else:
        msgs = []

        def option_text(o):
            return o if isinstance(o, str) else str(o.get("text", o)) if isinstance(o, dict) else str(o)

        def correct_index(q):
            c, opts = q["correct"], [option_text(o) for o in q["options"]]
            if isinstance(c, bool):
                return None
            if isinstance(c, int):
                return c
            if isinstance(c, str):
                if c.isdigit():
                    return int(c)
                if len(c) == 1 and c.upper() in "ABCDEFGH":
                    return ord(c.upper()) - 65
                if c in opts:
                    return opts.index(c)
            return None

        idx = [correct_index(q) for q in quiz]
        if None in idx:
            add("S10-quiz", "WARN", "could not read the correct answer positions; check by hand")
            quiz = None
    if quiz is not None:
        if len(quiz) != 5:
            msgs.append(f"{len(quiz)} questions")
        pos = idx
        if len(set(pos)) < 3:
            msgs.append(f"correct positions too uniform {pos}")
        if all(b - a == 1 for a, b in zip(pos, pos[1:])) or all(a - b == 1 for a, b in zip(pos, pos[1:])):
            msgs.append(f"correct positions follow a sequence {pos}")
        for i, q in enumerate(quiz):
            lens = [len(option_text(o)) for o in q["options"]]
            second = sorted(lens)[-2]
            if lens[idx[i]] == max(lens) and lens[idx[i]] > 1.15 * second:
                msgs.append(f"q{i + 1} correct option is conspicuously longest {lens}")
        add("S10-quiz", "FAIL" if msgs else "PASS", "; ".join(msgs) or f"positions {pos}")

    # S11 canaries must not appear in executable positions
    if canaries:
        hits = []
        for c in canaries:
            if c in code:
                hits.append(f"{c!r} in executable script")
            for tag, k, v in p.attrs:
                if c in v:
                    hits.append(f"{c!r} in <{tag} {k}>")
        add("S11-canaries-inert", "FAIL" if hits else "PASS", "; ".join(hits) or "none in executable positions")
    return res


def review_checks(block, snippets):
    """Returns (level, message) for the review-data block."""
    if block is None:
        return "FAIL", "no review-data block"
    try:
        d = json.loads(block["text"])
    except Exception as e:
        return "FAIL", f"review-data does not parse: {e}"
    msgs = []
    rows = d.get("whereToLook") or []
    if not rows:
        msgs.append("whereToLook is empty")
    for r in rows:
        if r.get("risk") not in RISKS:
            msgs.append(f"bad risk {r.get('risk')!r} for {r.get('file')}")
        if not r.get("reasons"):
            msgs.append(f"no reasons for {r.get('file')}")
    risky = {r.get("file") for r in rows if r.get("risk") in ("high", "medium")}
    traced = {c.get("file") for c in d.get("coverage") or [] if c.get("tests")}
    uncovered = set(d.get("uncovered") or [])
    missing = sorted(f for f in risky - traced - uncovered if f)
    if missing:
        msgs.append(f"High/Medium files with no traced test missing from uncovered: {missing}")
    claimed = sorted(f for f in uncovered & traced if f)
    if claimed:
        msgs.append(f"files listed as both covered and uncovered: {claimed}")
    rc = d.get("rootCause") or {}
    if rc.get("applies") and rc.get("verdict") not in VERDICTS:
        msgs.append(f"root cause applies but verdict is {rc.get('verdict')!r}")
    if (d.get("undo") or {}).get("kind") not in UNDO_KINDS:
        msgs.append(f"bad undo kind {(d.get('undo') or {}).get('kind')!r}")
    items = (d.get("forQa") or {}).get("items") or []
    if not 3 <= len(items) <= 7:
        msgs.append(f"{len(items)} For QA items (want 3 to 7)")
    rm = d.get("reviewMd") or {}
    skipped = set(rm.get("skipped") or [])
    if skipped:
        on_page = sorted({f for f in skipped if any(isinstance(v, dict) and v.get("file") == f for v in snippets.values())}
                         | {r.get("file") for r in rows if r.get("file") in skipped})
        if on_page:
            msgs.append(f"skipped paths still on the page: {on_page}")
    if not rm.get("present") and (rm.get("rules") or skipped):
        msgs.append("reviewMd rules or skipped paths without a REVIEW.md")
    return ("FAIL" if msgs else "PASS"), ("; ".join(msgs) or f"{len(rows)} ranked, {len(items)} For QA items")


def governance_checks(block, snippets, attrs, text, tags=()):
    """Returns (level, message) for the governance-data block and the control cards."""
    if block is None:
        return "FAIL", "no governance-data block"
    try:
        d = json.loads(block["text"])
    except Exception as e:
        return "FAIL", f"governance-data does not parse: {e}"
    msgs = []
    controls = d.get("controls") or []
    if d.get("present"):
        docs = d.get("documents") or []
        if not docs:
            msgs.append("present but no documents listed")
        for doc in docs:
            if not str(doc.get("path", "")).startswith("docs/governance/"):
                msgs.append(f"document outside docs/governance/: {doc.get('path')}")
            if doc.get("format") not in GOV_FORMATS:
                msgs.append(f"bad format {doc.get('format')!r} for {doc.get('path')}")
        for c in controls:
            for k in ("id", "requirement", "source"):
                if not c.get(k):
                    msgs.append(f"control {c.get('id')} has no {k}")
            if not c.get("files") and not str(c.get("id", "")).startswith("DOC-"):
                msgs.append(f"control {c.get('id')} has no files")
            for k in ("result", "status", "mark", "marked", "met", "passed", "verdict"):
                if k in c:
                    msgs.append(f"control {c.get('id')} carries {k!r}: the reviewer marks controls, not the page")
    elif controls:
        msgs.append("controls listed with present false")
    cards = {v for t, k, v in attrs if k == "data-control"}
    ids = {c.get("id") for c in controls}
    if ids - cards:
        msgs.append(f"controls with no card: {sorted(ids - cards)}")
    results = [v for t, k, v in attrs if k == "data-result"]
    if results and len(results) < 3 * len(ids):
        msgs.append("a control card lacks its Met, Not met, and Does not apply buttons")
    if any(t.get("data-result") in MARKS and t.get("aria-pressed") == "true" for t in tags):
        msgs.append("a governance button is pressed on load")
    said = sorted(set(m.group(0) for m in GOV_VERDICT.finditer(QUOTED.sub(" ", text))))
    if said:
        msgs.append(f"governance verdict in the page's voice: {said}")
    return ("FAIL" if msgs else "PASS"), ("; ".join(msgs) or f"{len(controls)} control(s), none marked")


def gate_checks(block, attrs):
    msgs = []
    if block is None:
        msgs.append("no gate-data block")
    else:
        try:
            d = json.loads(block["text"])
            if not d.get("commit"):
                msgs.append("gate-data has no commit")
        except Exception as e:
            msgs.append(f"gate-data does not parse: {e}")
    ids = {v for t, k, v in attrs if k == "id"}
    for need in ("gate-status", "quiz-reset", "gov-reset", "remediate", "gate-attestation"):
        if need not in ids:
            msgs.append(f"no #{need}")
    states = [v for t, k, v in attrs if k == "data-state"]
    if "gate-status" in ids and "blocked" not in states:
        msgs.append("gate does not start blocked")
    if any(v == "passed" for v in states):
        msgs.append("gate markup starts passed")
    return ("FAIL" if msgs else "PASS"), ("; ".join(msgs) or "gate starts blocked")


GATE_JS = """(cmd)=>{
 const Q=JSON.parse(document.getElementById('quiz-data').textContent);
 const state=()=>document.getElementById('gate-status').dataset.state;
 const click=e=>e.dispatchEvent(new MouseEvent('click',{bubbles:true}));
 const answer=(right)=>{document.querySelectorAll('#quiz-host .q').forEach((card,qi)=>{
   const q=Q[qi],want=q.options[q.correct];
   const opts=[...card.querySelectorAll('.opt')];
   const b=right(qi)?opts.find(o=>o.textContent===want):opts.find(o=>o.textContent!==want);
   if(b)click(b)})};
 const mark=(r)=>document.querySelectorAll('.gov-control').forEach((c,i)=>{const b=c.querySelector('[data-result="'+r(i)+'"]');if(b)click(b)});
 const out={};
 out.load=state();
 out.pressedOnLoad=document.querySelectorAll('.gov-control [aria-pressed="true"]').length;
 out.controls=document.querySelectorAll('.gov-control').length;
 answer(()=>true); out.quizOnly=state();
 mark(()=> 'met'); out.allGood=state();
 out.attestation=document.getElementById('gate-attestation').value;
 click(document.getElementById('quiz-reset')); out.afterRetake=state();
 out.unanswered=[...document.querySelectorAll('#quiz-host .opt')].filter(o=>o.disabled).length;
 answer(qi=>qi!==0); out.oneWrong=state();
 { const card=document.querySelector('#quiz-host .q'),want=Q[0].options[Q[0].correct];
   const b=[...card.querySelectorAll('.opt')].find(o=>o.textContent===want); b.disabled=false; click(b); out.secondTry=state(); }
 click(document.getElementById('quiz-reset')); answer(()=>true); out.retakeRight=state();
 if(out.controls){mark(i=>i===0?'notmet':'met'); out.notMet=state();
  out.remediateShown=!document.getElementById('remediate').hidden;
  click(document.getElementById('gov-reset')); out.afterGovReset=state();}
 return out}"""


def gate_dynamic(pg):
    """Drives the quiz and governance marks and checks every gate state."""
    o = pg.evaluate(GATE_JS)
    msgs = []
    if o["load"] != "blocked":
        msgs.append(f"loads {o['load']}")
    if o["pressedOnLoad"]:
        msgs.append(f"{o['pressedOnLoad']} governance button(s) pressed on load")
    if o["controls"] and o["quizOnly"] != "blocked":
        msgs.append(f"quiz alone gives {o['quizOnly']} with controls unmarked")
    if o["allGood"] != "passed":
        msgs.append(f"all right and all Met gives {o['allGood']}")
    else:
        try:
            a = json.loads(o["attestation"])
            if a.get("quiz", {}).get("correct") != 5 or a.get("source") != "explain-diff":
                msgs.append("attestation lacks the quiz score or source")
        except ValueError:
            msgs.append("no attestation JSON when passed")
    if o["afterRetake"] != "blocked":
        msgs.append(f"Retake gives {o['afterRetake']}")
    if o["unanswered"]:
        msgs.append("options still disabled after Retake")
    if o["oneWrong"] != "failed":
        msgs.append(f"one wrong answer gives {o['oneWrong']}")
    if o["secondTry"] != "failed":
        msgs.append(f"answering a locked question again gives {o['secondTry']}")
    if o["retakeRight"] != "passed":
        msgs.append(f"a right retake gives {o['retakeRight']}")
    if o["controls"]:
        if o["notMet"] != "failed":
            msgs.append(f"a Not met control gives {o['notMet']}")
        if not o["remediateShown"]:
            msgs.append("Remediation hidden with a Not met control")
        if o["afterGovReset"] != "blocked":
            msgs.append(f"Reset governance gives {o['afterGovReset']}")
    return ("FAIL" if msgs else "PASS"), ("; ".join(msgs) or f"blocked, passed, retake, failed, remediation all behave ({o['controls']} controls)")


def dynamic_checks(path, canaries):
    from playwright.sync_api import sync_playwright

    res = []
    abspath = os.path.abspath(path)
    with sync_playwright() as pw:
        browser = launch(pw)
        for width, height in ((1400, 900), (390, 844)):
            tag = f"{width}px"
            ctx = browser.new_context(viewport={"width": width, "height": height})
            pg = ctx.new_page()
            blocked, errs = [], []

            def on_route(route):
                u = route.request.url
                if u.startswith(("file://", "data:", "blob:")):
                    route.continue_()
                else:
                    blocked.append(u)
                    route.abort()

            pg.route("**/*", on_route)
            pg.on("pageerror", lambda e: errs.append(str(e)))
            pg.on("console", lambda m: errs.append(m.text) if m.type == "error" else None)
            pg.goto("file://" + abspath)
            pg.wait_for_timeout(300)
            scripts0 = pg.evaluate("document.scripts.length")
            n = pg.evaluate("""()=>{let n=0;document.querySelectorAll('[data-ref]').forEach(e=>{if(n<150){e.dispatchEvent(new MouseEvent('click',{bubbles:true}));n++}});
                document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}));return n}""")
            pg.wait_for_timeout(250)
            scripts1 = pg.evaluate("document.scripts.length")
            pwned = pg.evaluate("typeof window.__pwned !== 'undefined'")
            overflow = pg.evaluate("document.documentElement.scrollWidth>document.documentElement.clientWidth")
            panel = pg.evaluate("(()=>{const e=document.querySelector('#panel, aside');if(!e)return null;const r=e.getBoundingClientRect();return {w:Math.round(r.width),h:Math.round(r.height)}})()")
            res.append((f"D1-no-errors-{tag}", "FAIL" if errs else "PASS", "; ".join(errs[:3]) or f"clicked {n} reference(s)"))
            res.append((f"D2-no-network-{tag}", "FAIL" if blocked else "PASS", "; ".join(blocked[:3]) or "no requests"))
            res.append((f"D3-no-injected-scripts-{tag}", "FAIL" if (pwned or scripts1 != scripts0) else "PASS",
                        f"scripts {scripts0}->{scripts1}, canary executed: {pwned}"))
            res.append((f"D4-no-horizontal-overflow-{tag}", "FAIL" if overflow else "PASS", "overflow" if overflow else "none"))
            if width >= 900:
                ok = panel and panel["w"] >= 300 and panel["h"] >= 300
                res.append((f"D5-code-panel-present-{tag}", "PASS" if ok else "FAIL", str(panel)))
                pg.reload()
                pg.wait_for_timeout(200)
                try:
                    res.append(("D6-gate", *gate_dynamic(pg)))
                except Exception as e:
                    res.append(("D6-gate", "FAIL", f"gate could not be driven: {str(e)[:200]}"))
            ctx.close()
        browser.close()
    return res


def run(path, browser=False, canaries=()):
    res = static_checks(path, list(canaries))
    if browser:
        res += dynamic_checks(path, list(canaries))
    return res


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("page")
    ap.add_argument("--browser", action="store_true", help="also run Playwright checks")
    ap.add_argument("--canary", action="append", default=[], help="string that must never appear in executable positions")
    a = ap.parse_args()
    res = run(a.page, a.browser, a.canary)
    width = max(len(r[0]) for r in res)
    for cid, level, msg in res:
        print(f"{level:4}  {cid:{width}}  {msg}")
    fails = [r for r in res if r[1] == "FAIL"]
    print(f"\n{len(res) - len(fails)} passed or warned, {len(fails)} failed")
    sys.exit(1 if fails else 0)


if __name__ == "__main__":
    main()
